UPDATE gw_code_group
   SET group_nm = #{groupNm}, description = #{description}, use_yn = COALESCE(#{useYn}, use_yn)
 WHERE group_cd = #{groupCd}

UPDATE gw_code
   SET code_val = #{codeVal}, code_nm = #{codeNm},
       sort_no = COALESCE(#{sortNo}, sort_no),
       use_yn = COALESCE(#{useYn}, use_yn),
       extra_val = #{extraVal}
 WHERE code_id = #{codeId}
